export function collapsedText(element: Element | null | undefined): string {
  return (element?.textContent ?? '').replace(/\s+/g, ' ').trim();
}

function accessibleNameOf(element: Element): string {
  return element.getAttribute('aria-label')?.trim() ?? collapsedText(element);
}

export function findButton(root: Element, name: string): HTMLButtonElement | null {
  const buttons = Array.from(root.querySelectorAll('button'));
  return buttons.find((button) => accessibleNameOf(button) === name) ?? null;
}

export function getButton(root: Element, name: string): HTMLButtonElement {
  const button = findButton(root, name);
  if (!button) {
    throw new Error(`No button named "${name}" in: ${collapsedText(root)}`);
  }
  return button;
}

export function isDisabled(button: HTMLButtonElement): boolean {
  return button.disabled || button.getAttribute('aria-disabled') === 'true';
}

function ownLabelText(label: Element): string {
  const withoutControls = label.cloneNode(true) as Element;
  withoutControls.querySelectorAll('select, option, input').forEach((control) => control.remove());
  return collapsedText(withoutControls);
}

export function findSelect(root: Element, labelText: string): HTMLSelectElement | null {
  const byAriaLabel = Array.from(root.querySelectorAll('select')).find((select) => select.getAttribute('aria-label')?.trim() === labelText);
  if (byAriaLabel) {
    return byAriaLabel;
  }
  const labelElements = Array.from(root.querySelectorAll('label, [id]')).filter((candidate) => ownLabelText(candidate) === labelText);
  for (const labelElement of labelElements) {
    const nested = labelElement.querySelector('select');
    if (nested) {
      return nested;
    }
    const targetId = labelElement.getAttribute('for');
    const byFor = targetId ? root.querySelector(`select#${CSS.escape(targetId)}`) : null;
    if (byFor instanceof HTMLSelectElement) {
      return byFor;
    }
    const labelId = labelElement.getAttribute('id');
    const byLabelledBy = labelId
      ? Array.from(root.querySelectorAll('select')).find((select) => (select.getAttribute('aria-labelledby') ?? '').split(/\s+/).includes(labelId))
      : undefined;
    if (byLabelledBy) {
      return byLabelledBy;
    }
  }
  return null;
}

export function getSelect(root: Element, labelText: string): HTMLSelectElement {
  const select = findSelect(root, labelText);
  if (!select) {
    throw new Error(`No select labelled "${labelText}" in: ${collapsedText(root)}`);
  }
  return select;
}

export function optionTexts(select: HTMLSelectElement): string[] {
  return Array.from(select.options).map((option) => collapsedText(option));
}

export function selectedOptionText(select: HTMLSelectElement): string {
  return collapsedText(select.selectedOptions.item(0));
}

export function chooseOption(select: HTMLSelectElement, optionText: string): void {
  const option = Array.from(select.options).find((candidate) => collapsedText(candidate) === optionText);
  if (!option) {
    throw new Error(`No option "${optionText}" in select with options: ${optionTexts(select).join(', ')}`);
  }
  select.value = option.value;
  select.dispatchEvent(new Event('input', { bubbles: true }));
  select.dispatchEvent(new Event('change', { bubbles: true }));
}

export function locationRows(root: Element): HTMLElement[] {
  const tableRows = Array.from(root.querySelectorAll<HTMLElement>('tr')).filter((row) => row.querySelector('td') !== null);
  const ariaRows = Array.from(root.querySelectorAll<HTMLElement>('[role="row"]')).filter(
    (row) => row.tagName !== 'TR' && row.querySelector('[role="cell"], [role="gridcell"]') !== null,
  );
  return [...tableRows, ...ariaRows];
}

export function cellTexts(row: Element): string[] {
  return Array.from(row.querySelectorAll('td, th, [role="cell"], [role="gridcell"], [role="rowheader"]')).map((cell) => collapsedText(cell));
}

export function columnHeaderTexts(root: Element): string[] {
  return Array.from(root.querySelectorAll('th, [role="columnheader"]'))
    .filter((header) => header.closest('tbody') === null && header.getAttribute('scope') !== 'row' && header.getAttribute('role') !== 'rowheader')
    .map((header) => collapsedText(header));
}

export function hasTable(root: Element): boolean {
  return root.querySelector('table, [role="table"], [role="grid"]') !== null;
}

export function textOutsideTables(root: Element): string {
  const withoutTables = root.cloneNode(true) as Element;
  withoutTables.querySelectorAll('table, [role="table"], [role="grid"]').forEach((table) => table.remove());
  return collapsedText(withoutTables);
}
import { HttpErrorResponse } from '@angular/common/http';
import { Observable, Subject, from, switchMap, throwError, of } from 'rxjs';
import { AccountsApi } from '../app/core/api/accounts.api';
import { ActivityHealthApi, ActivityHealthRequest } from '../app/core/api/activity-health.api';
import { Account, ActivityHealthReport, EVENT_TYPES, ProblemDetails } from '../app/core/models';
import { EARLIEST_WEEK_BY_ACCOUNT_ID, LATEST_COMPLETE_WEEK, genericReport, scenarioReports, seedAccounts } from './activity-health-fixtures';

const MONDAY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function isMonday(week: string): boolean {
  if (!MONDAY_PATTERN.test(week)) {
    return false;
  }
  const parsed = new Date(`${week}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === week && parsed.getUTCDay() === 1;
}

function reportKey(accountId: number, weekStart: string, eventType: string): string {
  return `${accountId}|${weekStart}|${eventType}`;
}

function afterMicrotask<T>(outcome: () => Observable<T>): Observable<T> {
  return from(Promise.resolve()).pipe(switchMap(outcome));
}

export function validationProblem(field: string, message: string): HttpErrorResponse {
  const problem: ProblemDetails = {
    type: 'https://tools.ietf.org/html/rfc9110#section-15.5.1',
    title: 'One or more validation errors occurred.',
    status: 400,
    errors: { [field]: [message] },
  };
  return new HttpErrorResponse({ status: 400, statusText: 'Bad Request', error: problem });
}

export function notFoundProblem(): HttpErrorResponse {
  const problem: ProblemDetails = { title: 'Not Found', status: 404 };
  return new HttpErrorResponse({ status: 404, statusText: 'Not Found', error: problem });
}

export function serverError(): HttpErrorResponse {
  const problem: ProblemDetails = { title: 'An error occurred while processing your request.', status: 500 };
  return new HttpErrorResponse({ status: 500, statusText: 'Internal Server Error', error: problem });
}

export function networkFailure(): HttpErrorResponse {
  return new HttpErrorResponse({ status: 0, statusText: 'Unknown Error' });
}

export class FakeAccountsApi extends AccountsApi {
  listAccountsCalls = 0;
  readonly accounts: Account[] = seedAccounts();

  listAccounts(): Observable<Account[]> {
    this.listAccountsCalls += 1;
    return afterMicrotask(() => of(this.accounts.map((account) => ({ ...account }))));
  }
}

export class FakeActivityHealthApi extends ActivityHealthApi {
  readonly requests: ActivityHealthRequest[] = [];
  private readonly reportsByKey = new Map<string, ActivityHealthReport>();
  private readonly queuedFailures: HttpErrorResponse[] = [];
  private readonly heldResponses: { request: ActivityHealthRequest; response: Subject<ActivityHealthReport> }[] = [];
  private holdNextResponse = false;

  constructor(private readonly accounts: readonly Account[] = seedAccounts()) {
    super();
    scenarioReports().forEach((report) => this.register(report));
  }

  register(report: ActivityHealthReport): this {
    this.reportsByKey.set(reportKey(report.account.id, report.week.start, report.eventType), report);
    return this;
  }

  failNext(failure: HttpErrorResponse): this {
    this.queuedFailures.push(failure);
    return this;
  }

  holdNext(): this {
    this.holdNextResponse = true;
    return this;
  }

  releaseHeld(): void {
    const held = this.heldResponses.shift();
    if (!held) {
      throw new Error('No held activity-health request to release');
    }
    held.response.next(this.resolve(held.request));
    held.response.complete();
  }

  getActivityHealth(request: ActivityHealthRequest): Observable<ActivityHealthReport> {
    this.requests.push({ ...request });
    const queuedFailure = this.queuedFailures.shift();
    if (queuedFailure) {
      return afterMicrotask(() => throwError(() => queuedFailure));
    }
    if (this.holdNextResponse) {
      this.holdNextResponse = false;
      const response = new Subject<ActivityHealthReport>();
      this.heldResponses.push({ request: { ...request }, response });
      return response.asObservable();
    }
    return afterMicrotask(() => {
      const rejection = this.rejectionFor(request);
      return rejection ? throwError(() => rejection) : of(this.resolve(request));
    });
  }

  private rejectionFor(request: ActivityHealthRequest): HttpErrorResponse | null {
    const earliestWeek = EARLIEST_WEEK_BY_ACCOUNT_ID.get(request.accountId);
    if (!earliestWeek || !this.accounts.some((account) => account.id === request.accountId)) {
      return notFoundProblem();
    }
    if (!(EVENT_TYPES as readonly string[]).includes(request.eventType)) {
      return validationProblem('Type', 'The type field is invalid.');
    }
    if (request.week === null) {
      return null;
    }
    if (!isMonday(request.week)) {
      return validationProblem('Week', 'The week must be a Monday in yyyy-MM-dd format.');
    }
    if (request.week < earliestWeek || request.week > LATEST_COMPLETE_WEEK) {
      return validationProblem('Week', 'The week is outside the available range.');
    }
    return null;
  }

  private resolve(request: ActivityHealthRequest): ActivityHealthReport {
    const weekStart = request.week ?? LATEST_COMPLETE_WEEK;
    const registered = this.reportsByKey.get(reportKey(request.accountId, weekStart, request.eventType));
    if (registered) {
      return structuredClone(registered);
    }
    const account = this.accounts.find((candidate) => candidate.id === request.accountId);
    if (!account) {
      throw new Error(`Fake has no account ${request.accountId}`);
    }
    return genericReport(account, weekStart, request.eventType);
  }
}
import { TestBed } from '@angular/core/testing';
import { NavigationEnd, Params, Router } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';

export interface RecordedNavigation {
  url: string;
  replaceUrl: boolean;
}

export function recordNavigations(router: Router): RecordedNavigation[] {
  const navigations: RecordedNavigation[] = [];
  router.events.subscribe((event) => {
    if (event instanceof NavigationEnd) {
      navigations.push({ url: event.urlAfterRedirects, replaceUrl: router.lastSuccessfulNavigation()?.extras.replaceUrl === true });
    }
  });
  return navigations;
}

export function queryParamsOf(url: string): Params {
  return TestBed.inject(Router).parseUrl(url).queryParams;
}

export function currentQueryParams(): Params {
  const router = TestBed.inject(Router);
  return queryParamsOf(router.url);
}

export function currentPath(): string {
  const router = TestBed.inject(Router);
  const primary = router.parseUrl(router.url).root.children['primary'];
  return `/${primary ? primary.segments.map((segment) => segment.path).join('/') : ''}`;
}

export async function settle(harness?: RouterTestingHarness): Promise<void> {
  for (let round = 0; round < 12; round++) {
    await new Promise<void>((resolve) => setTimeout(resolve, 0));
    TestBed.tick();
    harness?.detectChanges();
  }
}
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { Account } from '../models';
import { seedAccounts } from '../../../testing/activity-health-fixtures';
import { AccountsApi, HttpAccountsApi } from './accounts.api';

describe('HttpAccountsApi', () => {
  let accountsApi: AccountsApi;
  let httpTesting: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting(), { provide: AccountsApi, useClass: HttpAccountsApi }],
    });
    accountsApi = TestBed.inject(AccountsApi);
    httpTesting = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpTesting.verify();
  });

  it('sends GET /api/accounts as a relative URL without query params', () => {
    accountsApi.listAccounts().subscribe();

    const request = httpTesting.expectOne((candidate) => candidate.urlWithParams === '/api/accounts');
    expect(request.request.method).toBe('GET');
    request.flush([]);
  });

  it('emits the accounts from the response body unchanged, including account 20', () => {
    const accountsInResponse = seedAccounts();
    let receivedAccounts: Account[] | undefined;

    accountsApi.listAccounts().subscribe((accounts) => (receivedAccounts = accounts));
    httpTesting.expectOne('/api/accounts').flush(accountsInResponse);

    expect(receivedAccounts).toEqual(accountsInResponse);
    expect(receivedAccounts?.some((account) => account.id === 20 && account.name === 'Quiet Harbor Spa')).toBe(true);
  });
});
