      expect(isDisabled(getButton(root, NEXT_WEEK))).toBe(false);
      expect(rowNames(root)).toEqual(['Site B', 'Site D']);
      expect(pageText(root)).not.toContain(EMPTY_ACCOUNT_MESSAGE);
